# WAR ARENA - AUTOMATIC trending from GMGN (no manual seed) - Installer
# The arena now pulls the live trending list from gmgn-cli market trending
# across sol/bsc/base/eth, with all display stats built in. No TRENDING_SEED needed.
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-auto-trending.ps1
$ErrorActionPreference = "Stop"
Write-Host "WAR - Automatic trending installer" -ForegroundColor Cyan
function Write-B64([string]$Path,[string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path,[System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/integration/gmgnTrendingSource.ts" ""
Write-B64 "src/integration/warRuntime.ts" ""
Write-B64 "tests/unit/gmgnTrendingSource.test.ts" ""

Write-Host ""; Write-Host "Building + testing ..." -ForegroundColor Cyan
npx tsc --noEmit; if ($LASTEXITCODE -ne 0){ throw "typecheck failed" }
npx vitest run
npm run build; if ($LASTEXITCODE -ne 0){ throw "build failed" }
Write-Host ""; Write-Host "Automatic trending installed. Expected: 1045 passed + 1 skipped, 486 guards." -ForegroundColor Green
Write-Host "Remove TRENDING_SEED from .env (no longer used). Restart: npm start, then open /trending." -ForegroundColor Yellow
